414:   function handleBackground(file) {
415:     if (!file || !file.type.startsWith("image/")) {
416:       toast("Escolha um arquivo de imagem.");
417:       return;
418:     }
419:     const reader = new FileReader();
420:     reader.onload = () => {
421:       const img = new Image();
422:       img.onload = () => {
423:         const max = 1600;
424:         const scale = Math.min(1, max / Math.max(img.width, img.height));
425:         const canvas = document.createElement("canvas");
426:         canvas.width = Math.round(img.width * scale);
427:         canvas.height = Math.round(img.height * scale);
428:         const ctx = canvas.getContext("2d");
429:         ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
430:         let dataUrl = canvas.toDataURL("image/jpeg", 0.82);
431:         try {
432:           localStorage.setItem("luna.probe", "1");
433:           localStorage.removeItem("luna.probe");
434:         } catch {
435:           /* ignore */
436:         }
437:         if (dataUrl.length > 3.6 * 1024 * 1024) {
438:           dataUrl = canvas.toDataURL("image/jpeg", 0.6);
439:         }
440:         applyBackground(dataUrl);
441:         saveState();
442:         toast("Fundo atualizado.");
443:       };
444:       img.onerror = () => toast("Não consegui ler essa imagem.");
445:       img.src = String(reader.result || "");
446:     };
447:     reader.onerror = () => toast("Não consegui ler esse arquivo.");
448:     reader.readAsDataURL(file);
449:   }
