451:   /* ---------- stars ---------- */
452: 
453:   const canvas = $("#stars");
454:   const ctx = canvas.getContext("2d");
455:   let stars = [];
456:   let starFrame = 0;
457:   let starWidth = 0;
458:   let starHeight = 0;
459:   let starDpr = 1;
460: 
461:   function buildStars() {
462:     const count = Math.round(Math.min(90, Math.max(34, starWidth / 18)));
463:     stars = Array.from({ length: count }, () => ({
464:       x: Math.random() * starWidth,
465:       y: Math.random() * starHeight,
466:       r: 0.4 + Math.random() * 1.5,
467:       a: 0.15 + Math.random() * 0.55,
468:       v: 0.08 + Math.random() * 0.25,
469:       p: Math.random() * Math.PI * 2
470:     }));
471:   }
472: 
473:   function resizeStars() {
474:     starDpr = Math.min(window.devicePixelRatio || 1, 2);
475:     starWidth = window.innerWidth;
476:     starHeight = window.innerHeight;
477:     canvas.width = Math.round(starWidth * starDpr);
478:     canvas.height = Math.round(starHeight * starDpr);
479:     canvas.style.width = `${starWidth}px`;
480:     canvas.style.height = `${starHeight}px`;
481:     ctx.setTransform(starDpr, 0, 0, starDpr, 0, 0);
482:     buildStars();
483:   }
484: 
485:   function drawStars(time) {
486:     ctx.clearRect(0, 0, starWidth, starHeight);
487:     const t = (time || 0) / 1000;
488:     for (const star of stars) {
489:       const y = (star.y + t * star.v * 6) % starHeight;
490:       const twinkle = 0.65 + Math.sin(t * 1.4 + star.p) * 0.35;
491:       ctx.beginPath();
492:       ctx.arc(star.x, y, star.r, 0, Math.PI * 2);
493:       ctx.fillStyle = `rgba(190, 232, 255, ${(star.a * twinkle).toFixed(3)})`;
494:       ctx.fill();
495:     }
496:   }
497: 
498:   function starLoop(time) {
499:     drawStars(time);
500:     starFrame = window.requestAnimationFrame(starLoop);
501:   }
502: 
503:   function startStars() {
504:     window.cancelAnimationFrame(starFrame);
505:     starFrame = 0;
506:     if (!state.animations) {
507:       drawStars(0);
508:       return;
509:     }
510:     starFrame = window.requestAnimationFrame(starLoop);
511:   }
