+    ctx.shadowBlur = 0; ctx.strokeStyle = "rgba(220,205,238,.64)"; ctx.lineWidth = 1.2;
+    ctx.beginPath(); ctx.moveTo(-2, -moth.r * .38); ctx.quadraticCurveTo(-10, -moth.r * .9, -11, -moth.r * .82); ctx.moveTo(2, -moth.r * .38); ctx.quadraticCurveTo(10, -moth.r * .9, 11, -moth.r * .82); ctx.stroke();
+    ctx.restore();
+  }
+  function drawPlayer(time) {
+    const bob = Math.sin(time * .004) * 3;
+    if (invincible > 0 && Math.floor(time / 90) % 2) return;
+    ctx.save(); ctx.translate(player.x, player.y + bob);
+    ctx.shadowColor = "rgba(176,218,255,.6)"; ctx.shadowBlur = 26;
+    ctx.fillStyle = "rgba(212,233,255,.15)"; ctx.beginPath(); ctx.ellipse(0, 8, 28, 31, 0, 0, TAU); ctx.fill();
+    ctx.shadowBlur = 0;
+    // Flowing hair and face
+    ctx.fillStyle = "#75546b"; ctx.beginPath(); ctx.ellipse(0, -8, 20, 25, 0, 0, TAU); ctx.fill();
+    ctx.fillStyle = "#ffddce"; ctx.beginPath(); ctx.ellipse(0, -5, 14, 17, 0, 0, TAU); ctx.fill();
+    ctx.fillStyle = "#79566d"; ctx.beginPath(); ctx.moveTo(-14, -12); ctx.quadraticCurveTo(-11, -30, 7, -24); ctx.quadraticCurveTo(19, -20, 15, -3); ctx.quadraticCurveTo(8, -15, 1, -15); ctx.quadraticCurveTo(-6, -8, -15, -6); ctx.closePath(); ctx.fill();
+    ctx.fillStyle = "#91dff2"; ctx.beginPath(); ctx.ellipse(-5, -4, 2.4, 3.5, 0, 0, TAU); ctx.ellipse(5, -4, 2.4, 3.5, 0, 0, TAU); ctx.fill();
+    ctx.fillStyle = "#32405b"; ctx.beginPath(); ctx.arc(-5, -3, 1.1, 0, TAU); ctx.arc(5, -3, 1.1, 0, TAU); ctx.fill();
+    ctx.strokeStyle = "#c87882"; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.arc(0, 2, 3, .15, Math.PI - .15); ctx.stroke();
+    ctx.fillStyle = "#f4f1ff"; ctx.beginPath(); ctx.moveTo(-12, 12); ctx.quadraticCurveTo(0, 7, 12, 12); ctx.lineTo(17, 33); ctx.quadraticCurveTo(0, 40, -17, 33); ctx.closePath(); ctx.fill();
+    ctx.fillStyle = "#ffdf8a"; ctx.beginPath(); ctx.moveTo(0, 14); ctx.lineTo(4, 19); ctx.lineTo(0, 24); ctx.lineTo(-4, 19); ctx.closePath(); ctx.fill();
+    ctx.strokeStyle = "#ffddce"; ctx.lineWidth = 5; ctx.lineCap = "round"; ctx.beginPath(); ctx.moveTo(-12, 18); ctx.lineTo(-19, 25); ctx.moveTo(12, 18); ctx.lineTo(19, 25); ctx.stroke();
+    ctx.restore();
+  }
+  function render(time) {
+    drawBackground(time);
+    for (const seed of seeds) drawSeed(seed, time);
+    for (const moth of moths) drawMoth(moth, time);
+    drawPlayer(time);
+    for (const particle of particles) {
+      ctx.globalAlpha = clamp(particle.life / particle.maxLife, 0, 1); ctx.fillStyle = particle.color;
+      ctx.beginPath(); ctx.arc(particle.x, particle.y, particle.size, 0, TAU); ctx.fill();
+    }
+    ctx.globalAlpha = 1;
+  }
+  function frame(time) {
+    const dt = Math.min(.04, (time - (lastFrame || time)) / 1000);
+    lastFrame = time;
+    step(dt); render(time);
+    requestAnimationFrame(frame);
+  }
+  requestAnimationFrame(frame);
+
+  document.querySelector("#startButton").addEventListener("click", startGame);
+  document.querySelector("#playAgainButton").addEventListener("click", startGame);
+  document.querySelector("#restartPauseButton").addEventListener("click", startGame);
+  document.querySelector("#resumeButton").addEventListener("click", resumeGame);
+  document.querySelector("#homeButton").addEventListener("click", () => {
+    state = "ready"; resultScreen.hidden = true; welcome.hidden = false; pauseButton.disabled = true;
+  });
+  pauseButton.addEventListener("click", () => state === "paused" ? resumeGame() : pauseGame());
+  document.querySelector("#soundButton").addEventListener("click", (event) => {
+    soundOn = !soundOn;
+    document.querySelector("#soundIcon").textContent = soundOn ? "♫" : "♪";
+    event.currentTarget.setAttribute("aria-label", soundOn ? "Desativar som" : "Ativar som");
+    event.currentTarget.classList.toggle("is-on", soundOn);
+    if (soundOn) beep(660, .16);
+  });
+  window.addEventListener("keydown", (event) => {
+    if (["ArrowLeft", "ArrowRight", " "].includes(event.key)) event.preventDefault();
+    keys.add(event.key);
+    if ((event.key === "Escape" || event.key.toLowerCase() === "p") && !event.repeat) state === "playing" ? pauseGame() : resumeGame();
+    if (event.key === "Enter" && state === "ready") startGame();
+  });
+  window.addEventListener("keyup", (event) => keys.delete(event.key));
+  window.addEventListener("blur", () => keys.clear());
+  canvas.addEventListener("pointerdown", (event) => {
+    if (state !== "playing") return;
+    pointer.active = true; pointer.x = event.clientX - canvas.getBoundingClientRect().left;
+    canvas.setPointerCapture?.(event.pointerId);
+  });
+  canvas.addEventListener("pointermove", (event) => {
+    if (pointer.active) pointer.x = event.clientX - canvas.getBoundingClientRect().left;
+  });
+  const stopPointer = () => { pointer.active = false; };
+  canvas.addEventListener("pointerup", stopPointer); canvas.addEventListener("pointercancel", stopPointer);
+  document.addEventListener("visibilitychange", () => { if (document.hidden && state === "playing") pauseGame(); });
+})();

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');

:root {
  color-scheme: dark;
  --ink: #f9f4e9;
  --muted: #b7b4c7;
  --gold: #f3d795;
  --gold-dark: #d7b86e;
  --glass: rgba(25, 30, 52, .66);
  font-family: 'DM Sans', 'Segoe UI', sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}
* { box-sizing: border-box; }
html, body { width: 100%; height: 100%; margin: 0; }
body {
  min-width: 320px;
  min-height: 100%;
  overflow: hidden;
  color: var(--ink);
  background: #101629;
}
button { color: inherit; font: inherit; }
button:focus-visible { outline: 2px solid #fff0bd; outline-offset: 4px; }
[hidden] { display: none !important; }
.game-shell {
  width: min(100%, 1600px);
  height: 100dvh;
  min-height: 440px;
  margin: 0 auto;
  padding: 0 42px;
  display: grid;
  grid-template-rows: 86px minmax(0, 1fr) 48px;
  background: #141a2b;
}
.topbar { display: flex; align-items: center; justify-content: space-between; z-index: 3; }
.brand { display: inline-flex; gap: 12px; align-items: center; color: var(--ink); text-decoration: none; }
.brand-mark {
  display: grid; place-items: center; width: 43px; height: 43px; border: 1px solid rgba(243,215,149,.4);
  border-radius: 15px; color: var(--gold); font-size: 25px; line-height: 1; background: rgba(248,226,179,.08);
}
.brand strong, .brand small { display: block; }
.brand strong { font-family: 'Playfair Display', Georgia, serif; font-size: 17px; font-weight: 600; letter-spacing: .01em; }
.brand small { margin-top: 2px; color: #a7a5b8; font-size: 10px; letter-spacing: .09em; text-transform: uppercase; }
.top-actions { display: flex; gap: 9px; }
.icon-button {
  width: 40px; height: 40px; display: grid; place-items: center; border-radius: 13px;
  border: 1px solid rgba(234,229,255,.14); background: rgba(255,255,255,.055); color: #d6d4e5; font-size: 19px;
  transition: background .2s, border-color .2s, transform .2s;
}
.icon-button:hover:not(:disabled) { transform: translateY(-2px); background: rgba(255,255,255,.12); border-color: rgba(243,215,149,.4); }
.icon-button:disabled { opacity: .38; cursor: default; }
.icon-button.is-on { color: var(--gold); }
.game-stage {
  position: relative; min-height: 0; overflow: hidden; isolation: isolate; border-radius: 23px;
  border: 1px solid rgba(229,219,255,.14); background: #17213a; box-shadow: 0 24px 70px rgba(0,0,0,.24);
}
#gameCanvas { display: block; width: 100%; height: 100%; touch-action: none; }
.scene-vignette { position: absolute; inset: 0; z-index: 0; pointer-events: none; box-shadow: inset 0 0 100px rgba(9,12,25,.25); }
.hud { position: absolute; z-index: 1; top: 20px; left: 22px; right: 22px; display: flex; align-items: flex-start; justify-content: space-between; pointer-events: none; }
.hud-card {
  min-width: 105px; padding: 10px 14px 11px; border: 1px solid rgba(255,255,255,.13); border-radius: 14px;
  background: rgba(22,28,48,.66); backdrop-filter: blur(12px); box-shadow: 0 8px 26px rgba(9,13,27,.13);
}
.hud-label { display: block; margin-bottom: 4px; color: #c3bfd1; font-size: 9px; font-weight: 700; letter-spacing: .16em; }
.hud-card strong { display: block; color: #fff8e9; font-size: 19px; line-height: 1.15; font-weight: 600; }
.goal-card strong i { color: #b7b4c6; font-size: 12px; font-style: normal; }
.progress-track { width: 88px; height: 3px; margin-top: 8px; overflow: hidden; border-radius: 9px; background: rgba(255,255,255,.18); }
.progress-track span { display: block; width: 0; height: 100%; border-radius: inherit; background: var(--gold); transition: width .25s ease; }
.timer-card { min-width: 85px; text-align: center; }
.timer-card strong { font-variant-numeric: tabular-nums; }
.timer-card strong.urgent { color: #ffaaa7; animation: pulse .7s ease infinite alternate; }
.lives-card { text-align: right; }
.lives-card strong { color: #f2a9b5; font-size: 16px; letter-spacing: .1em; white-space: nowrap; }
.screen { position: absolute; z-index: 2; inset: 0; display: flex; align-items: center; justify-content: center; }
.welcome-screen {
  align-items: stretch; justify-content: flex-start; padding: clamp(36px, 7.5vw, 104px) clamp(34px, 8.3vw, 116px);
  overflow: hidden; background: linear-gradient(90deg, rgba(17,24,44,.96) 0%, rgba(19,27,49,.92) 42%, rgba(22,30,53,.34) 73%, rgba(22,30,53,.12) 100%);
}
.welcome-copy { position: relative; z-index: 1; width: min(55%, 510px); align-self: center; margin-top: -3px; }
.eyebrow { color: var(--gold); font-size: 10px; font-weight: 700; letter-spacing: .19em; }
.sparkle { margin-right: 7px; font-size: 15px; vertical-align: -1px; }
h1, h2, p { margin-top: 0; }
h1 { margin: 19px 0 14px; color: #fff9ee; font-family: 'Playfair Display', Georgia, serif; font-size: clamp(34px, 4vw, 54px); line-height: 1.12; font-weight: 600; letter-spacing: -.025em; }
.welcome-copy > p { max-width: 405px; margin-bottom: 21px; color: #c5c6d1; font-size: 14px; line-height: 1.75; }
.how-to { display: flex; align-items: center; gap: 16px; margin: 23px 0 28px; color: #d0ccdb; font-size: 12px; }
.how-item { display: flex; align-items: center; gap: 5px; }
.keycap { display: inline-grid; place-items: center; width: 24px; height: 25px; border: 1px solid rgba(255,255,255,.22); border-radius: 6px; background: rgba(255,255,255,.07); color: #f4e7c7; font-size: 12px; }
.how-divider { width: 1px; height: 25px; background: rgba(255,255,255,.17); }
.pointer-icon { margin-right: 3px; color: var(--gold); font-size: 20px; }
.primary-button {
  display: inline-flex; min-height: 48px; align-items: center; justify-content: center; gap: 22px; padding: 0 20px;
  border: 1px solid #f5dfac; border-radius: 10px; background: linear-gradient(135deg, #f8e6b9, #e6ca8e); color: #302d37;
  box-shadow: 0 9px 26px rgba(222,190,126,.19); font-size: 13px; font-weight: 700; transition: transform .18s, filter .18s, box-shadow .18s;
}
.primary-button:hover { transform: translateY(-2px); filter: brightness(1.05); box-shadow: 0 12px 30px rgba(222,190,126,.27); }
.primary-button span { font-size: 18px; font-weight: 400; }
.best-score { margin: 16px 0 0 !important; color: #aeadbd !important; font-size: 11px !important; }
.best-score strong { color: #e8dfc9; font-weight: 600; }
.welcome-character { position: absolute; right: 6.5%; bottom: 4%; width: min(38%, 355px); height: 91%; display: flex; align-items: center; justify-content: center; }
.character-aura { position: absolute; width: 78%; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle, rgba(173,162,210,.31), rgba(169,162,218,.08) 49%, transparent 72%); filter: blur(4px); }
.character-moon { position: absolute; top: 10%; right: 14%; color: #f4dda9; font-size: 49px; transform: rotate(-20deg); text-shadow: 0 0 30px rgba(245,221,169,.35); }
.luna-art { position: relative; height: 90%; max-width: 100%; filter: drop-shadow(0 16px 30px rgba(10,12,24,.35)); animation: float 4s ease-in-out infinite; }
.welcome-label { position: absolute; bottom: 2%; color: rgba(240,226,196,.7); font-size: 8px; letter-spacing: .2em; white-space: nowrap; }
.welcome-footer { position: absolute; bottom: 20px; left: 50%; display: flex; gap: 9px; transform: translateX(-50%); color: rgba(223,220,231,.54); font-size: 8px; letter-spacing: .16em; white-space: nowrap; }
.welcome-footer span:nth-child(2) { color: var(--gold); }
.stage-caption { position: absolute; z-index: 1; bottom: 18px; left: 50%; display: flex; align-items: center; gap: 8px; transform: translateX(-50%); color: rgba(249,244,233,.72); font-size: 11px; text-shadow: 0 1px 5px #101629; white-space: nowrap; transition: opacity .2s; }
.stage-caption.is-playing { opacity: 0; }
.caption-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 12px var(--gold); }
.toast { position: absolute; z-index: 5; top: 88px; left: 50%; padding: 10px 15px; transform: translate(-50%, -8px); border: 1px solid rgba(255,255,255,.16); border-radius: 10px; background: rgba(30,34,55,.88); color: #fff0d3; font-size: 12px; opacity: 0; pointer-events: none; transition: opacity .2s, transform .2s; }
.toast.show { transform: translate(-50%, 0); opacity: 1; }
.pause-screen, .result-screen { background: rgba(13,17,32,.56); backdrop-filter: blur(5px); }
.modal-card { width: min(420px, calc(100% - 34px)); padding: 32px 34px 26px; border: 1px solid rgba(255,255,255,.17); border-radius: 21px; background: rgba(29,35,57,.95); box-shadow: 0 24px 70px rgba(0,0,0,.36); text-align: center; animation: rise .3s ease both; }
.modal-card.compact { width: min(360px, calc(100% - 34px)); padding-top: 28px; }
.modal-icon { display: grid; width: 46px; height: 46px; place-items: center; margin: 0 auto 17px; border: 1px solid rgba(243,215,149,.32); border-radius: 15px; color: var(--gold); font-size: 20px; }
.modal-card h2 { margin: 10px 0 8px; color: #fff8e9; font-family: 'Playfair Display', Georgia, serif; font-size: 29px; font-weight: 600; }
.modal-card p { margin: 0 0 22px; color: #c0bdcd; font-size: 13px; line-height: 1.6; }
.modal-card .primary-button { width: 100%; }
.text-button { display: block; margin: 13px auto 0; padding: 7px 10px; border: 0; background: transparent; color: #c4bfd0; font-size: 12px; }
.text-button:hover { color: #fff2d6; }
.result-kicker { color: var(--gold); font-size: 9px; font-weight: 700; letter-spacing: .2em; }
.result-star { margin: 10px 0 0; color: #f3d795; font-size: 39px; text-shadow: 0 0 25px rgba(255,226,158,.28); }
.result-stats { display: grid; grid-template-columns: repeat(3, 1fr); margin: 20px 0 23px; padding: 15px 0; border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.1); }
.result-stats div + div { border-left: 1px solid rgba(255,255,255,.1); }
.result-stats strong, .result-stats span { display: block; }
.result-stats strong { color: #fff1d2; font-size: 20px; font-weight: 600; }
.result-stats span { margin-top: 4px; color: #aaa8b9; font-size: 9px; }
.footer { display: flex; align-items: center; justify-content: space-between; color: #85869a; font-size: 9px; letter-spacing: .09em; }
.footer > span:first-child { font-weight: 700; }
.footer > span:last-child { letter-spacing: .03em; text-transform: none; }
.footer b, .footer-moon { padding: 0 5px; color: var(--gold); }
@keyframes float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-9px); } }
@keyframes pulse { to { opacity: .6; } }
@keyframes rise { from { opacity: 0; transform: translateY(9px) scale(.98); } to { opacity: 1; transform: translateY(0) scale(1); } }
@media (max-width: 760px) {
  .game-shell { padding: 0 18px; grid-template-rows: 70px minmax(0,1fr) 42px; }
  .game-stage { border-radius: 17px; }
  .welcome-screen { padding: 35px 30px 54px; background: linear-gradient(90deg, rgba(17,24,44,.96), rgba(19,27,49,.84) 64%, rgba(22,30,53,.48)); }
  .welcome-copy { width: 67%; align-self: center; }
  h1 { font-size: clamp(31px, 6vw, 44px); }
  .welcome-copy > p { max-width: 360px; font-size: 13px; }
  .welcome-character { right: -5%; width: 43%; opacity: .76; }
  .hud { top: 13px; left: 13px; right: 13px; }
  .hud-card { min-width: 84px; padding: 8px 10px; border-radius: 11px; }
  .progress-track { width: 67px; }
  .timer-card { min-width: 69px; }
  .lives-card strong { font-size: 13px; }
}
@media (max-width: 520px) {
  .game-shell { min-height: 420px; padding: 0 10px; grid-template-rows: 62px minmax(0,1fr) 36px; }
  .brand { gap: 9px; }
  .brand-mark { width: 36px; height: 36px; border-radius: 12px; font-size: 21px; }
  .brand strong { font-size: 15px; }
  .brand small { font-size: 8px; }
  .icon-button { width: 35px; height: 35px; border-radius: 11px; }
  .welcome-screen { padding: 28px 22px 48px; background: linear-gradient(90deg, rgba(17,24,44,.97), rgba(19,27,49,.9) 72%, rgba(22,30,53,.65)); }
  .welcome-copy { width: 100%; align-self: center; }
  .welcome-copy > p { max-width: 310px; padding-right: 5px; font-size: 12px; }
  h1 { margin-top: 15px; font-size: clamp(34px, 9.5vw, 43px); }
  .how-to { gap: 10px; margin: 18px 0 22px; font-size: 10px; }
  .keycap { width: 21px; height: 22px; }
  .primary-button { min-height: 45px; font-size: 12px; }
  .welcome-character { right: -18%; bottom: 2%; width: 65%; height: 62%; opacity: .32; }
  .welcome-footer { bottom: 13px; font-size: 7px; }
  .hud { top: 10px; left: 8px; right: 8px; gap: 5px; }
  .hud-card { min-width: auto; padding: 7px 8px; background: rgba(22,28,48,.74); }
  .hud-label { font-size: 7px; }
  .hud-card strong { font-size: 16px; }
  .goal-card strong i { font-size: 10px; }
  .progress-track { width: 55px; margin-top: 6px; }
  .timer-card { min-width: 59px; }
  .lives-card strong { font-size: 11px; letter-spacing: .04em; }
  .stage-caption { bottom: 12px; font-size: 9px; }
  .footer { font-size: 7px; }
  .footer > span:last-child { font-size: 8px; }
  .modal-card { padding: 26px 23px 20px; }
}
@media (max-height: 560px) and (min-width: 521px) {
  .game-shell { grid-template-rows: 64px minmax(0,1fr) 36px; }
  .welcome-screen { padding-top: 24px; padding-bottom: 38px; }
  h1 { margin: 12px 0 9px; font-size: 36px; }
  .welcome-copy > p { margin-bottom: 12px; font-size: 12px; }
  .how-to { margin: 12px 0 15px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

