36: function resolvePath(urlPath) {
37:   let decoded;
38:   try {
39:     decoded = decodeURIComponent(urlPath);
40:   } catch {
41:     return null;
42:   }
43:   const target = normalize(join(root, decoded));
44:   if (target !== root && !target.startsWith(root + sep)) return null;
45:   return target;
46: }
47: 
48: async function readStatic(requestPath) {
49:   const target = resolvePath(requestPath);
50:   if (!target) return null;
51:   try {
52:     const info = await stat(target);
53:     if (info.isDirectory()) {
54:       return { file: join(target, "index.html"), info: await stat(join(target, "index.html")) };
55:     }
56:     return { file: target, info };
57:   } catch {
58:     return null;
59:   }
60: }
61: 
62: const server = createServer(async (req, res) => {
63:   const url = new URL(req.url || "/", "http://localhost");
64:   let found = await readStatic(url.pathname);
